// Source = articles réellement publiés (flux https://maxmorrys.me/rss.xml), et non plus la banque d'idées.
// Correction 2026-10-29 (audit éditorial S4) : la lettre ne met plus en avant des brouillons sans URL.
const seen = new Set();
const articles = $input.all().map(i => i.json)
  .filter(a => a && a.title && a.link && !seen.has(a.link) && seen.add(a.link))
  .sort((a, b) => new Date(b.isoDate || b.pubDate || 0) - new Date(a.isoDate || a.pubDate || 0))
  .slice(0, 5)
  .map(a => ({ titre: a.title, url: a.link, date: (a.isoDate || a.pubDate || '').slice(0, 10), categorie: Array.isArray(a.categories) ? a.categories[0] : (a.categories || ''), resume: String(a.contentSnippet || a.content || '').slice(0, 300) }));
if (!articles.length) { console.log('WF-09 : aucun article publié dans le flux RSS, rien à rédiger'); return []; }
return [{ json: { recent_articles: articles, article_principal: articles[0] } }];

// Correction 2026-10-29 : le noeud Gemini v1.1 renvoie {content:{parts:[{text}]}}, pas {candidates:[...]}.
const r = $input.first().json;
const text = r.content?.parts?.map(p => p.text || "").join("") || r.candidates?.[0]?.content?.parts?.[0]?.text || r.text || "";
const clean = String(text).replace(/^\s*```(?:json)?\s*/i, "").replace(/\s*```\s*$/, "");
let newsletter;
try { newsletter = JSON.parse(clean); }
catch (e) { throw new Error("Erreur parsing newsletter (finishReason=" + (r.finishReason || "?") + "): " + e.message); }
return [{ json: {
  subject: newsletter.subject || "Newsletter Max-Morrys",
  preview_text: newsletter.preview_text || "",
  html_body: newsletter.html_body || "",
  plain_text: newsletter.plain_text || "",
  main_cta: newsletter.main_cta || {},
  article_url: $("Préparer — Contenu newsletter").first().json.article_principal.url,
  generated_at: new Date().toISOString(),
  status: "draft"
} }];

